def solve(inputs: dict) -> float:
    # find the list of terms
    terms = None
    for v in inputs.values():
        if isinstance(v, (list, tuple)):
            terms = list(v)
            break
    if terms is None:
        # maybe single string
        for v in inputs.values():
            if isinstance(v, str):
                import re
                nums = re.findall(r'-?\d+', v)
                if len(nums) > 1:
                    terms = [int(x) for x in nums]
                    break
    terms = [int(t) for t in terms]
    p_prev = 1
    p = 0
    # standard convergent recurrence: p_n = a_n * p_{n-1} + p_{n-2}
    # init p_{-1}=1, p_{-2}=0
    for a in terms:
        p, p_prev = a*p + p_prev, p
    return float(p)

